mapper.sql:
WHERE document.use_yn = 'Y'

    AND document.document_scope = #{documentScope}


    AND document.document_status = #{documentStatus}


    AND document.member_id = #{authorId}


    AND EXISTS (
        SELECT 1 FROM document_tags tag_filter
        WHERE tag_filter.document_id = document.document_id AND tag_filter.tag_name = #{tag}
    )




            AND document.document_title LIKE CONCAT('%', #{searchKeyword}, '%')


            AND document.content_text LIKE CONCAT('%', #{searchKeyword}, '%')


            AND member.member_name LIKE CONCAT('%', #{searchKeyword}, '%')


            AND (
                document.document_title LIKE CONCAT('%', #{searchKeyword}, '%')
                OR document.content_text LIKE CONCAT('%', #{searchKeyword}, '%')
            )

mapper.select:
SELECT document.document_id, document.member_id AS author_id, member.member_name AS author_name, document.document_title, document.document_scope, document.thumbnail_file_id, CASE WHEN document.thumbnail_file_id IS NULL THEN NULL ELSE CONCAT('/api/v1/files/', document.thumbnail_file_id, '/content') END AS thumbnail_image_url,
CAST(document.content_json AS CHAR) AS content_json, document.content_html, document.content_text, document.document_status, document.version_number, document.view_count, document.use_yn, document.deleted_at, document.created_at, document.updated_at
FROM documents document INNER JOIN members member ON member.member_id = document.member_id WHERE document.document_id = #{documentId}

mapper.update:
UPDATE documents
SET use_yn = 'N', deleted_at = CURRENT_TIMESTAMP(6), updated_at = CURRENT_TIMESTAMP(6)
WHERE document_id = #{documentId}
  AND member_id = #{memberId}
  AND document_scope = #{documentScope}
  AND use_yn = 'Y'

UPDATE documents
SET use_yn = 'Y', deleted_at = NULL, updated_at = CURRENT_TIMESTAMP(6)
WHERE document_id = #{documentId}
  AND member_id = #{memberId}
  AND document_scope = #{documentScope}
  AND use_yn = 'N'

mapper.delete:
DELETE FROM document_files
WHERE document_id = #{documentId}
  AND file_role = 'ATTACHMENT'

mapper.select:
SELECT tag.tag_name, COUNT(*) AS document_count
FROM document_tags tag
INNER JOIN documents document ON document.document_id = tag.document_id
WHERE document.use_yn = 'Y'
  AND document.document_scope = #{documentScope}
  AND document.member_id = #{authorId}
  AND document.document_status = #{documentStatus}
GROUP BY tag.tag_name
ORDER BY document_count DESC, tag.tag_name
LIMIT 30
